[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>SnapFrame — Capture, Create & Share What You Love</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --black: #000000;
      --white: #ffffff;
      --purple: #7638FA;
      --orange: #FF7A00;
      --magenta: #E040A0;
      --gray-50: #F9FAFB;
      --gray-100: #F3F4F6;
      --gray-200: #E5E7EB;
      --gray-400: #9CA3AF;
      --gray-500: #6B7280;
      --gray-600: #4B5563;
      --gray-700: #374151;
      --gray-800: #1F2937;
      --gray-900: #111827;
      --radius: 16px;
      --radius-sm: 10px;
      --radius-pill: 999px;
      --gradient-brand: linear-gradient(135deg, var(--purple), var(--magenta), var(--orange));
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      color: var(--gray-900);
      background: var(--white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; display: block; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* ===== HEADER ===== */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: rgba(255, 255, 255, 0.92);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid var(--gray-200);
    }

    .header__inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
    }

    .header__logo {
      font-size: 1.25rem;
      font-weight: 800;
      letter-spacing: -0.02em;
      background: var(--gradient-brand);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .header__actions {
      display: flex;
      align-items: center;
      gap: 16px;
    }

    .btn-login {
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--white);
      background: var(--black);
      padding: 8px 20px;
      border-radius: var(--radius-pill);
      transition: opacity 0.2s;
    }
    .btn-login:hover { opacity: 0.85; }

    .hamburger {
      display: none;
      flex-direction: column;
      justify-content: center;
      align-items: center;
      width: 40px;
      height: 40px;
      gap: 5px;
      z-index: 1001;
    }
    .hamburger span {
      display: block;
      width: 22px;
      height: 2px;
      background: var(--black);
      border-radius: 2px;
      transition: transform 0.3s, opacity 0.3s;
    }
    .hamburger.active span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
    .hamburger.active span:nth-child(2) { opacity: 0; }
    .hamburger.active span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

    .mobile-nav {
      display: none;
      position: fixed;
      inset: 0;
      background: var(--white);
      z-index: 999;
      padding: 100px 32px 32px;
      flex-direction: column;
      gap: 8px;
    }
    .mobile-nav.open { display: flex; }
    .mobile-nav a {
      font-size: 1.5rem;
      font-weight: 700;
      padding: 12px 0;
      border-bottom: 1px solid var(--gray-200);
      transition: color 0.2s;
    }
    .mobile-nav a:hover { color: var(--purple); }

    @media (max-width: 768px) {
      .hamburger { display: flex; }
      .header__nav-desktop { display: none; }
    }

    .header__nav-desktop {
      display: flex;
      align-items: center;
      gap: 32px;
    }
    .header__nav-desktop a {
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--gray-600);
      transition: color 0.2s;
    }
    .header__nav-desktop a:hover { color: var(--black); }

    /* ===== HERO ===== */
    .hero {
      padding: 140px 0 100px;
      position: relative;
      overflow: hidden;
      background: linear-gradient(165deg, #FAF5FF 0%, #FFF7ED 40%, #FFFFFF 80%);
    }
    .hero::before {
      content: '';
      position: absolute;
      top: -120px;
      right: -100px;
      width: 500px;
      height: 500px;
      background: radial-gradient(circle, rgba(118, 56, 250, 0.12) 0%, transparent 70%);
      border-radius: 50%;
      pointer-events: none;
    }
    .hero::after {
      content: '';
      position: absolute;
      bottom: -80px;
      left: -60px;
      width: 400px;
      height: 400px;
      background: radial-gradient(circle, rgba(255, 122, 0, 0.1) 0%, transparent 70%);
      border-radius: 50%;
      pointer-events: none;
    }

    .hero__content {
      position: relative;
      z-index: 1;
      max-width: 780px;
    }

    .hero__tag {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 0.8rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--purple);
      margin-bottom: 24px;
    }
    .hero__tag span {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--gradient-brand);
    }

    .hero__title {
      font-size: clamp(2.5rem, 5.5vw, 4rem);
      font-weight: 800;
      line-height: 1.08;
      letter-spacing: -0.03em;
      color: var(--black);
      margin-bottom: 24px;
    }

    .hero__subtitle {
      font-size: 1.125rem;
      color: var(--gray-600);
      max-width: 560px;
      line-height: 1.7;
      margin-bottom: 40px;
    }

    .btn-cta {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      font-size: 1rem;
      font-weight: 700;
      color: var(--white);
      background: var(--gradient-brand);
      padding: 16px 36px;
      border-radius: var(--radius-pill);
      transition: transform 0.2s, box-shadow 0.2s;
      box-shadow: 0 4px 24px rgba(118, 56, 250, 0.3);
    }
    .btn-cta:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 32px rgba(118, 56, 250, 0.4);
    }
    .btn-cta svg { width: 18px; height: 18px; }

    /* ===== SECTION SHARED ===== */
    .section {
      padding: 100px 0;
    }
    .section--gray { background: var(--gray-50); }

    .section__label {
      font-size: 0.75rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--purple);
      margin-bottom: 12px;
    }

    .section__title {
      font-size: clamp(1.75rem, 3.5vw, 2.75rem);
      font-weight: 800;
      line-height: 1.15;
      letter-spacing: -0.02em;
      margin-bottom: 20px;
    }
    .section__title a { transition: color 0.2s; }
    .section__title a:hover { color: var(--purple); }

    .section__desc {
      font-size: 1.0625rem;
      color: var(--gray-600);
      max-width: 620px;
      line-height: 1.7;
      margin-bottom: 28px;
    }

    .section__link {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 0.9375rem;
      font-weight: 700;
      color: var(--purple);
      transition: gap 0.2s;
    }
    .section__link:hover { gap: 10px; }

    /* ===== FEATURES ===== */
    .features {
      position: relative;
    }
    .features__grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 24px;
      margin-top: 48px;
    }
    .feature-card {
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius);
      padding: 32px;
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .feature-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 40px rgba(0, 0, 0, 0.06);
    }
    .feature-card__icon {
      width: 48px;
      height: 48px;
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 16px;
      font-size: 1.25rem;
    }
    .feature-card__icon--clips { background: linear-gradient(135deg, #7638FA20, #7638FA40); color: var(--purple); }
    .feature-card__icon--stories { background: linear-gradient(135deg, #FF7A0020, #FF7A0040); color: var(--orange); }
    .feature-card__icon--dms { background: linear-gradient(135deg, #E040A020, #E040A040); color: var(--magenta); }
    .feature-card__icon--explore { background: linear-gradient(135deg, #10B98120, #10B98140); color: #10B981; }
    .feature-card__name {
      font-size: 1rem;
      font-weight: 700;
      margin-bottom: 6px;
    }
    .feature-card__text {
      font-size: 0.875rem;
      color: var(--gray-500);
      line-height: 1.6;
    }

    @media (max-width: 600px) {
      .features__grid { grid-template-columns: 1fr; }
    }

    /* ===== SAFETY ===== */
    .safety {
      background: linear-gradient(180deg, #FAF5FF 0%, var(--white) 100%);
    }
    .safety__badges {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      margin-top: 32px;
    }
    .safety-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-pill);
      padding: 10px 20px;
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--gray-700);
      transition: border-color 0.2s;
    }
    .safety-badge:hover { border-color: var(--purple); }
    .safety-badge svg {
      width: 18px;
      height: 18px;
      color: var(--purple);
    }

    /* ===== CREATORS ===== */
    .creators {
      position: relative;
      background: var(--black);
      color: var(--white);
      overflow: hidden;
    }
    .creators::before {
      content: '';
      position: absolute;
      top: -200px;
      right: -100px;
      width: 600px;
      height: 600px;
      background: radial-gradient(circle, rgba(118, 56, 250, 0.2) 0%, transparent 60%);
      pointer-events: none;
    }
    .creators::after {
      content: '';
      position: absolute;
      bottom: -150px;
      left: -80px;
      width: 500px;
      height: 500px;
      background: radial-gradient(circle, rgba(255, 122, 0, 0.15) 0%, transparent 60%);
      pointer-events: none;
    }
    .creators .section__label { color: var(--orange); }
    .creators .section__desc { color: rgba(255, 255, 255, 0.65); }
    .creators .section__link { color: var(--orange); }
    .creators .container { position: relative; z-index: 1; }

    .creators__stats {
      display: flex;
      gap: 48px;
      margin-top: 40px;
    }
    .creators__stat-number {
      font-size: 2rem;
      font-weight: 800;
      background: var(--gradient-brand);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .creators__stat-text {
      font-size: 0.875rem;
      color: rgba(255, 255, 255, 0.5);
      margin-top: 4px;
    }

    @media (max-width: 600px) {
      .creators__stats { gap: 32px; flex-wrap: wrap; }
    }

    /* ===== TAGLINE BANNER ===== */
    .tagline {
      padding: 80px 0;
      text-align: center;
      background: var(--gradient-brand);
      color: var(--white);
    }
    .tagline__text {
      font-size: clamp(1.5rem, 3.5vw, 2.5rem);
      font-weight: 800;
      letter-spacing: -0.02em;
      max-width: 600px;
      margin: 0 auto;
    }

    /* ===== NEWS ===== */
    .news { overflow: hidden; }

    .news__header {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: 40px;
      flex-wrap: wrap;
      gap: 16px;
    }

    .news__viewmore {
      font-size: 0.9375rem;
      font-weight: 700;
      color: var(--purple);
      transition: opacity 0.2s;
    }
    .news__viewmore:hover { opacity: 0.7; }

    .news__carousel {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      padding-bottom: 16px;
      scrollbar-width: thin;
      scrollbar-color: var(--gray-300) transparent;
    }
    .news__carousel::-webkit-scrollbar { height: 6px; }
    .news__carousel::-webkit-scrollbar-track { background: transparent; }
    .news__carousel::-webkit-scrollbar-thumb {
      background: var(--gray-400);
      border-radius: 3px;
    }

    .news-card {
      min-width: 300px;
      max-width: 340px;
      flex-shrink: 0;
      scroll-snap-align: start;
      border-radius: var(--radius);
      overflow: hidden;
      background: var(--white);
      border: 1px solid var(--gray-200);
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .news-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 40px rgba(0, 0, 0, 0.08);
    }
    .news-card:first-child { margin-left: 0; }

    .news-card__thumb {
      width: 100%;
      height: 180px;
      position: relative;
      overflow: hidden;
    }
    .news-card__thumb--1 { background: linear-gradient(135deg, #7638FA, #E040A0); }
    .news-card__thumb--2 { background: linear-gradient(135deg, #FF7A00, #FFB347); }
    .news-card__thumb--3 { background: linear-gradient(135deg, #E040A0, #7638FA); }
    .news-card__thumb--4 { background: linear-gradient(135deg, #10B981, #7638FA); }

    .news-card__thumb-icon {
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      width: 56px;
      height: 56px;
      border-radius: 16px;
      background: rgba(255, 255, 255, 0.2);
      backdrop-filter: blur(8px);
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .news-card__thumb-icon svg { width: 24px; height: 24px; color: white; }

    .news-card__body {
      padding: 20px;
    }

    .news-card__tags {
      display: flex;
      flex-wrap: wrap;
      gap: 6px;
      margin-bottom: 12px;
    }

    .news-card__tag {
      font-size: 0.6875rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      color: var(--purple);
      background: rgba(118, 56, 250, 0.08);
      padding: 4px 10px;
      border-radius: var(--radius-pill);
    }

    .news-card__title {
      font-size: 0.9375rem;
      font-weight: 700;
      line-height: 1.4;
      margin-bottom: 12px;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .news-card__date {
      font-size: 0.8125rem;
      color: var(--gray-400);
      font-weight: 500;
    }

    /* ===== CTA DOWNLOAD ===== */
    .cta-download {
      padding: 100px 0;
      text-align: center;
      background: var(--gray-50);
    }
    .cta-download__title {
      font-size: clamp(2rem, 4vw, 3.25rem);
